function [s] = modes_enter(st, mode)
%MODES_ENTER  Enter a controller state: the dwell timers reset, the integral cleared; the states that skip
%   estimation (detumble, thruster detumble, spin-up, Sun spin) drop the attitude estimate; spin-up
%   starts its spin-sign window.
%   st: Modes (passed rec)
%   mode: int (passed a whole number)
%   returns s: Modes (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = asils.relations.shared.Modes_zero();
    s = st;
    if (mode == 5)
        s.sz_sum = 0;
        s.sz_n = 0;
        s.sz_t0 = s.t;
    end
    s.mode = mode;
    s.t_mode = s.t;
    s.hold = 0;
    s.ho = false;
    s.ho_t = 0;
    if ((((mode == 0) || (mode == 7)) || (mode == 5)) || (mode == 6))
        s.ad_ok = false;
        s.n_rej = 0;
    end
    s.i_q = zeros(3, 1);
end
